345	%  opr juxtaposition(self, other: ZZ): ZZ
346	\Method{\EXP{\KWD{opr}\;\;\KWD{juxtaposition}(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
347	
348	Juxtaposition of integer expressions is equivalent to using the multiplication operator \EXP{\cdot}.
349	
350	
351	%%   opr +(self): ZZ
352	%%   opr BOXPLUS(self): ZZ
353	%%   opr DOTPLUS(self): ZZ
354	\Method{\EXP{\KWD{opr} +(\KWD{self})\COLON \mathbb{Z}}}
355	\Method*{\EXP{\KWD{opr} \mathord{\boxplus}(\KWD{self})\COLON \mathbb{Z}}}
356	\Method*{\EXP{\KWD{opr} \mathord{\dotplus}(\KWD{self})\COLON \mathbb{Z}}}
357	
358	The unary addition operator \EXP{+} simply returns its argument.
359	The operators \EXP{\boxplus} and \EXP{\dotplus} do exactly the same thing.
360	
361	%%   opr +(self, other: ZZ): ZZ
362	%%   opr BOXPLUS(self, other: ZZ): ZZ
363	%%   opr DOTPLUS(self, other: ZZ): ZZ
364	\Method{\EXP{\KWD{opr} +(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
365	\Method*{\EXP{\KWD{opr} \mathord{\boxplus}(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
366	\Method*{\EXP{\KWD{opr} \mathord{\dotplus}(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
367	
368	The binary addition operator \EXP{+} returns the sum of its arguments.
369	The wrapping and saturating addition operators \EXP{\boxplus} and \EXP{\dotplus} do exactly the same thing,
370	because operations on type \EXP{\mathbb{Z}} never need to wrap or saturate.
371	
372	
373	%%   opr -(self): QQ
374	%%   opr BOXMINUS(self): QQ
375	%%   opr DOTMINUS(self): QQ
376	\Method{\EXP{\KWD{opr} -(\KWD{self})\COLON \mathbb{Q}}}
377	\Method*{\EXP{\KWD{opr} \mathord{\boxminus}(\KWD{self})\COLON \mathbb{Q}}}
378	\Method*{\EXP{\KWD{opr} \mathord{\dotminus}(\KWD{self})\COLON \mathbb{Q}}}
379	
380	The unary negation operator \EXP{-} returns the negative of its argument.
381	The operators \EXP{\boxminus} and \EXP{\dotminus} do exactly the same thing.
382	
383	
384	%%   opr -(self, other: ZZ): ZZ
385	%%   opr BOXMINUS(self, other: ZZ): ZZ
386	%%   opr DOTMINUS(self, other: ZZ): ZZ
387	\Method{\EXP{\KWD{opr} -(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
388	\Method*{\EXP{\KWD{opr} \mathord{\boxminus}(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
389	\Method*{\EXP{\KWD{opr} \mathord{\dotminus}(\KWD{self}, \VAR{other}\COLON \mathbb{Z})\COLON \mathbb{Z}}}
390	
391	The binary subtraction operator \EXP{-} returns the difference of its arguments,
392	which is equal to the sum of (a) the first argument and (b) the negation of the second argument.
393	The wrapping and saturating subtraction operators \EXP{\boxminus} and \EXP{\dotminus} do exactly the same thing,
394	because operations on type ZZ never need to wrap or saturate.
395	
